import sys, json, subprocess, datetime

def entries(fn):
    out = subprocess.run(['git','show','origin/conversation-logs:'+fn],capture_output=True,text=True,cwd='/home/user/Claudinite')
    for l in out.stdout.splitlines():
        l=l.strip()
        if not l: continue
        try: yield json.loads(l)
        except Exception: pass

def ts(e):
    t=e.get('timestamp')
    if not t: return None
    try: return datetime.datetime.fromisoformat(t.replace('Z','+00:00'))
    except Exception: return None

def main(fn, mode='digest'):
    es=list(entries(fn))
    times=[ts(e) for e in es if ts(e)]
    print('=== FILE:',fn,'entries:',len(es))
    if times: print('span:',times[0].isoformat(),'->',times[-1].isoformat(),'=',round((times[-1]-times[0]).total_seconds()),'s')
    # user prompts
    prompts=[]
    for e in es:
        if e.get('type')=='user' and isinstance(e.get('message'),dict):
            c=e['message'].get('content')
            if isinstance(c,str): prompts.append((e.get('timestamp'),c))
            elif isinstance(c,list):
                for b in c:
                    if isinstance(b,dict) and b.get('type')=='text':
                        prompts.append((e.get('timestamp'),b['text']))
    print('--- USER PROMPTS (%d) ---'%len(prompts))
    for t,p in prompts:
        p=p.strip()
        if p.startswith('<'): p='[sysreminder-ish] '+p[:200]
        print('[%s] %s'%(t, p[:1500].replace('\n',' | ')))
    # assistant text
    print('--- ASSISTANT TEXT ---')
    for e in es:
        if e.get('type')=='assistant' and isinstance(e.get('message'),dict):
            for b in e['message'].get('content',[]):
                if isinstance(b,dict) and b.get('type')=='text' and b.get('text','').strip():
                    print('[%s] %s'%(e.get('timestamp'), b['text'][:2000].replace('\n',' | ')))
    # tool timings: pair tool_use uuid -> tool_result entry
    uses={}
    for e in es:
        if e.get('type')=='assistant' and isinstance(e.get('message'),dict):
            for b in e['message'].get('content',[]):
                if isinstance(b,dict) and b.get('type')=='tool_use':
                    uses[b['id']]=(b.get('name'), json.dumps(b.get('input'))[:300], ts(e))
    durs=[]
    for e in es:
        if e.get('type')=='user' and isinstance(e.get('message'),dict):
            c=e['message'].get('content')
            if isinstance(c,list):
                for b in c:
                    if isinstance(b,dict) and b.get('type')=='tool_result':
                        tid=b.get('tool_use_id')
                        if tid in uses:
                            n,inp,t0=uses[tid]; t1=ts(e)
                            if t0 and t1: durs.append(((t1-t0).total_seconds(), n, inp))
    total=sum(d[0] for d in durs)
    print('--- TOOL WALL CLOCK: %d calls, total %.0fs ---'%(len(durs),total))
    durs.sort(reverse=True)
    for d,n,inp in durs[:12]:
        print('  %.0fs  %s  %s'%(d,n,inp.replace('\n',' ')[:180]))
    # aggregate by tool
    agg={}
    for d,n,inp in durs:
        a=agg.setdefault(n,[0,0.0]); a[0]+=1; a[1]+=d
    print('  by tool:', sorted(((round(v[1]),k,v[0]) for k,v in agg.items()),reverse=True)[:10])

if __name__=='__main__':
    for fn in sys.argv[1:]:
        main(fn)
